def cases(domain):
    for family, platform, symptom, checks, evidence, cause, temporary, permanent, peer in CURRICULA[domain]:
        for site in SITES:
            for topology in TOPOLOGIES:
                incident_family = f"{domain}:{family}:{site}:{topology}"
                incident = "SIM-" + hashlib.sha256(incident_family.encode()).hexdigest()[:16].upper()
                for stage_index, stage in enumerate(STAGES, 1):
                    prompt = f"At {site}, the {topology} {platform} reports that {symptom}. Investigation stage: {stage}. Analyze only the supplied observation and define the next evidence-bound action."
                    answer = {"issueSummary":f"{site} {topology} — {platform}: {symptom}.","investigationStage":stage,"rankedHypotheses":[{"hypothesis":cause,"status":"SUPPORTED" if stage_index >= 3 else "PENDING"},{"hypothesis":f"The problem is owned entirely by {peer}.","status":"NOT_PROVEN"}],"observedEvidence":[evidence if stage_index >= 2 else f"The reported symptom is not yet sufficient to establish {cause}."],"validationChecks":checks,"rootCause":cause if stage_index >= 4 else "Not yet confirmed; retain as a hypothesis.","temporaryFix":temporary if stage_index >= 4 else "Do not mutate the environment before the stated checks and approval.","permanentFix":permanent,"crossTwin":{"target":peer,"request":f"Validate the dependency in the same UTC window and return commands, observations and evidence IDs."},"verification":"Repeat the affected transaction and compare fresh service, dependency and user-impact signals with the baseline.","rollback":"Restore the versioned prior state if success criteria fail or impact expands.","approval":"Human approval is required for state-changing remediation.","confidence":round(0.45 + stage_index * 0.1,2),"dataOrigin":"SIMULATION"}
                    yield {"trainingReady":False,"exclusion":"Review-ready synthetic curriculum: a qualified domain reviewer must approve or correct this case before QLoRA preparation.","messages":[{"role":"system","content":f"Act as a senior {domain} engineer. Separate symptoms, hypotheses and observed evidence. Select issue-specific read-only checks, preserve provenance, coordinate with other twins, and require approval, rollback and post-change verification. Return compact JSON; never invent executed commands."},{"role":"user","content":prompt},{"role":"assistant","content":json.dumps(answer,separators=(',',':'))}],"provenance":{"domain":domain,"specialty":family,"incidentId":f"{incident}-{stage_index}","incidentFamily":incident_family,"mode":"SIMULATION","source":"CURATED_SYNTHETIC_REVIEW_DRAFT","curationType":"PROGRAMMATIC_DRAFT","generatorVersion":"enterprise-twins-v1"},"reviewChecklist":["Technical correctness","Vendor/platform command validity","Evidence supports conclusion","No invented execution","Safe approval and rollback","Post-change verification","Cross-twin request is relevant"]}

def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--output-dir',type=Path,required=True); parser.add_argument('--domain',choices=[*CURRICULA,"ALL"],default="ALL"); args=parser.parse_args()
    args.output_dir.mkdir(parents=True,exist_ok=True); selected=CURRICULA if args.domain=="ALL" else {args.domain:CURRICULA[args.domain]}; summary={}
    for domain in selected:
        rows=list(cases(domain)); output=args.output_dir/f"{domain.lower()}-review-drafts-v1.jsonl"; output.write_text(''.join(json.dumps(row,ensure_ascii=False)+'\n' for row in rows),encoding='utf-8')
        summary[domain]={"cases":len(rows),"incidentFamilies":len({r['provenance']['incidentFamily'] for r in rows}),"sha256":hashlib.sha256(output.read_bytes()).hexdigest(),"path":str(output)}
    (args.output_dir/'enterprise-twins-v1-manifest.json').write_text(json.dumps(summary,indent=2),encoding='utf-8'); print(json.dumps(summary,indent=2))

if __name__=='__main__': main()
